local function polygon(im,points,col)
 for yy=0,im.height-1 do for xx=0,im.width-1 do
  local inside=false;local j=#points
  for i=1,#points do local a=points[i];local b=points[j]
   if ((a[2]>yy)~=(b[2]>yy)) and xx<(b[1]-a[1])*(yy-a[2])/(b[2]-a[2])+a[1] then inside=not inside end
   j=i
  end
  if inside then rect(im,xx,yy,1,1,col) end
 end end
end
